# “文学与通识”书多，挑出最值得先插读的 10 本（✨），其余按兴趣挑
PICK_MARK = "✨"
ANYTIME_PICKS = ["唐诗三百首", "宋词三百首", "浮生六记", "人间草木", "三体", "额尔古纳河右岸",
                 "了不起的盖茨比", "杀死一只知更鸟", "寂静的春天", "观看之道"]

# 随时选读按用途分三类：(名称, 说明, 领域)；领域为 None 的一类收其余全部
ANYTIME_GROUPS = [
    ("文学与通识", f"读主线累了换换脑子：诗词、小说、历史与科普艺术；书多，先读带{PICK_MARK}的 {len(ANYTIME_PICKS)} 本，"
                   "其余挑感兴趣的读", None),
    ("实用与成长", "遇到具体问题时读：理财投资、创业、心理、人际沟通、健康、写作和影像创作",
     {"经济与财富", "投资与理财", "商业与创业", "心理与人生", "人际与关系", "健康与生命", "写作与表达", "影像与视频创作",
      "思维与方法"}),
    ("陪孩子", "孩子到了哪个年龄、遇到什么问题，就读对应的那本", {"教育与家庭"}),
]


def anytime_group(domain):
    return next(name for name, _, domains in ANYTIME_GROUPS[1:] + ANYTIME_GROUPS[:1]
                if domains is None or domain in domains)

