def min_age(age):
    return int(re.search(r"\d+", age).group())


def age_band(age):
    """按起始年龄归入前 4 个年龄段：<6、6-8、9-11、12+。"""
    limits = [6, 9, 12, math.inf]
    return next(b for (b, _), limit in zip(KID_BANDS, limits) if min_age(age) < limit)


FAMILY_READS = {k[0] for k in FAMILY_KIDS}
FAMILY_MARK = "👨‍👩‍👧‍👦"
KIDS += [(age_band(k[4]), *k) for k in FAMILY_KIDS]

