MUST_MARK = "🔖"


def kid_title(title, quote=False, grade=False):
    """亲子书名：必读加 🔖，全家共读加 👨‍👩‍👧‍👦，课内必读加 📚；grade=True 时在 📚 后标出年级。"""
    name = f"《{title}》" if quote else title
    if title in KID_MUST_TITLES:
        name += MUST_MARK
    if title in FAMILY_READS:
        name += FAMILY_MARK
    if title in TEXTBOOK_GRADE:
        name += TEXTBOOK_MARK + (TEXTBOOK_GRADE[title] if grade else "")
    return name


_BAND_ORDER = [b for b, _ in KID_BANDS]
KIDS.sort(key=lambda k: (_BAND_ORDER.index(k[0]) if k[0] in _BAND_ORDER else 99, min_age(k[5])))


def special_topics():
    return [b.split("｜")[0] for b, _ in KID_BANDS if b.endswith("专题")]


