def preface_md(adult=True, kids=True, level="###"):
    """把导读渲染成 Markdown；两部分都要时分小标题。"""
    out = []
    for title, emoji, a, k in preface():
        out += [f"{level} {emoji} {title}", ""]
        parts = [("成人书单", a)] * adult + [("亲子共读", k)] * kids
        for name, items in parts:
            if len(parts) > 1:
                out += [f"**{name}**", ""]
            out += [f"- **{lead}**：{text}" for lead, text in items] + [""]
    return out


def write_route(wb, rows, main_col):
    ws = wb.create_sheet("阅读路线")
    headers = ["序号", "书名", "作者", "领域", "并行线/分类", "建议用时(周)", "本线累计(周)", "难度(1-5)", "级别", "状态（自动同步）"]
    widths = [7, 24, 22, 12, 9, 11, 12, 9, 7, 14]
    style_header(ws, headers, widths)
    status_ref = f"总书单!${main_col['状态']}:${main_col['状态']}"
    title_ref = f"总书单!${main_col['书名']}:${main_col['书名']}"

    ws.cell(row=2, column=1, value=f"读法：每个阶段{THREE_LINES}状态列会自动读取「总书单」里的填写。")
    ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=len(headers))
    ws.cell(row=2, column=1).alignment = WRAP
    ws.row_dimensions[2].height = 36

    r = 3
    first_data = r
    group_desc = {g: desc for g, desc, _ in ANYTIME_GROUPS}
    for phase, summary, items in phase_plan(rows):
        cell = ws.cell(row=r, column=1, value=summary)
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=len(headers))
        cell.fill, cell.font, cell.alignment = PHASE_FILL, Font(bold=True, color="1F3864"), WRAP
        ws.row_dimensions[r].height = 34
        r += 1
        group = None
        for idx, (b, line, running) in enumerate(items, 1):
            if not phase and line != group:
                group = line
                n = sum(1 for _, x, _ in items if x == group)
                cell = ws.cell(row=r, column=1, value=f"▸ {group}（{n} 本）：{group_desc[group]}")
                ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=len(headers))
                cell.font, cell.alignment = Font(bold=True, color="595959"), WRAP
                r += 1
            t = b["书名"]
            values = [idx, t, b["作者"], b["领域"], line + (PICK_MARK if t in ANYTIME_PICKS else ""), b["建议用时(周)"],
                      running, b["难度(1-5)"], b["级别"],
                      f'=IFERROR(INDEX({status_ref},MATCH(B{r},{title_ref},0)),"")']
            for c, v in enumerate(values, 1):
                cell = ws.cell(row=r, column=c, value=v)
                cell.border = BORDER
                cell.alignment = WRAP if c in (2, 3) else CENTER
            ws.cell(row=r, column=2).font = Font(bold=True)
            ws.row_dimensions[r].height = row_height(values[:9], widths[:9])
            r += 1
    ws.freeze_panes = "C2"
    add_status_colors(ws, "J", first_data, r - 1)
    for text, color in (("必读", "F8CBAD"), ("推荐", "FFE699"), ("拓展", "E7E6E6")):
        ws.conditional_formatting.add(
            f"I{first_data}:I{r - 1}",
            CellIsRule(operator="equal", formula=[f'"{text}"'], fill=PatternFill("solid", fgColor=color)))


def write_year(wb, rows, main_col):
    ws = wb.create_sheet("年度12本")
    headers = ["月份", "主题", "大人读", "作者", "状态（自动同步）", *[f"孩子读（{t}）" for t in YEAR_TIERS],
               "一起做", "饭桌上聊"]
    widths = [7, 14, 22, 18, 12, 18, 18, 18, 18, 40, 44]
    style_header(ws, headers, widths)
    status_ref = f"总书单!${main_col['状态']}:${main_col['状态']}"
    title_ref = f"总书单!${main_col['书名']}:${main_col['书名']}"
    ws.cell(row=2, column=1, value=YEAR_NOTE)
    ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=len(headers))
    ws.cell(row=2, column=1).alignment = WRAP
    ws.row_dimensions[2].height = 36
    by_title = {r["书名"]: r for r in rows}
    for r, (month, theme, adult, kids, todo, questions) in enumerate(YEAR_PLAN, 3):
        values = [f"{month}月", theme, adult, by_title[adult]["作者"],
                  f'=IFERROR(INDEX({status_ref},MATCH(C{r},{title_ref},0)),"")',
                  *kids, todo, "\n".join(f"{n} {q}" for n, q in zip("①②③", questions))]
        for c, v in enumerate(values, 1):
            cell = ws.cell(row=r, column=c, value=v)
            cell.border = BORDER
            cell.alignment = CENTER if c in (1, 2, 5) else WRAP
        ws.cell(row=r, column=3).font = Font(bold=True)
        ws.row_dimensions[r].height = max(row_height(values[:4] + values[5:-1], widths[:4] + widths[5:-1]),
                                          sum(row_height([q], widths[-1:]) - 4 for q in questions) + 4)
    ws.freeze_panes = "C3"
    add_status_colors(ws, "E", 3, len(YEAR_PLAN) + 2)


def write_kids(wb):
    ws = wb.create_sheet("亲子共读")
    style_header(ws, KIDS_HEADERS, KIDS_WIDTHS)
    for i, k in enumerate(KIDS, 2):
        values = [f"K{i - 1:03d}", k[0], kid_title(k[1]), *k[2:], MEDIA.get(k[1], ""), kid_level(k[1]),
                  TEXTBOOK_GRADE.get(k[1], ""), *[None] * len(KID_READERS)]
        for c, v in enumerate(values, 1):
            cell = ws.cell(row=i, column=c, value=v)
            cell.border = BORDER
            cell.alignment = WRAP if c in (3, 4, 5, 6, 8, 9, 10) else CENTER
        ws.cell(row=i, column=3).font = Font(bold=True)
        ws.row_dimensions[i].height = row_height(values, KIDS_WIDTHS)
    last = len(KIDS) + 1
    ws.freeze_panes = "D2"
    ws.auto_filter.ref = f"A1:{get_column_letter(len(KIDS_HEADERS))}{last}"
    first, end = (get_column_letter(KIDS_HEADERS.index(n) + 1) for n in (KID_READERS[0], KID_READERS[-1]))
    dv = DataValidation(type="list", formula1=STATUS_OPTIONS, allow_blank=True)
    dv.add(f"{first}2:{end}{last}")
    ws.add_data_validation(dv)
    add_status_colors(ws, f"{first}", 2, last)
    for name in KID_READERS[1:]:
        add_status_colors(ws, get_column_letter(KIDS_HEADERS.index(name) + 1), 2, last)
    add_level_colors(ws, get_column_letter(KIDS_HEADERS.index("级别") + 1), last)
    for (text, _), color in zip(KID_BANDS, BAND_COLORS):
        ws.conditional_formatting.add(
            f"B2:B{last}", CellIsRule(operator="equal", formula=[f'"{text}"'], fill=PatternFill("solid", fgColor=color)))


def write_guide(wb, rows, main_col):
    ws = wb.active
    ws.title = "使用说明"
    ws.column_dimensions["A"].width = 22
    ws.column_dimensions["B"].width = 14
    ws.column_dimensions["C"].width = 14
    ws.column_dimensions["D"].width = 14
    ws.column_dimensions["E"].width = 12

    ws["A1"] = "人类智慧经典书单"
    ws["A1"].font = Font(bold=True, size=18, color="1F3864")
    ws["A2"] = f"成人主书单 {len(rows)} 本，覆盖 {len(BOOKS)} 个领域；亲子共读 {len(KIDS)} 本"
    ws["A2"].font = Font(color="595959")

    r = 4
    guide = [
        ("工作表", f"「年度12本」每月一本成人书配同主题的亲子书；「总书单」查找和记录；「阅读路线」按阶段排好顺序；「亲子共读」按年龄段分组，另设{'、'.join(special_topics())} "
                   f"{len(special_topics())} 个专题，每本标注阅读年龄；书名带{MUST_MARK}的是先读的必读（「级别」列可筛选），"
                   f"带{FAMILY_MARK}的适合全家一起读，"
                   f"带{TEXTBOOK_MARK}的是孩子语文课内必读，「课内必读」列标注了年级。"),
        ("级别", LEVEL_NOTE),
        ("内容定位", POSITION_NOTE + "「总书单」的「内容定位」列可以筛选。"),
        ("难度", "1＝轻松好读，2＝普通，3＝需要专注，4＝需要导读或注释，5＝硬核巨著。"),
        ("阅读阶段", f"①入门筑基 → ②经典核心 → ③深入精读 → ④高峰攻坚；{ANYTIME_NOTE}"),
        ("三线并行", THREE_LINES),
        ("八大主题", THEME_NOTE + "「总书单」的「主题」列可以筛选。"),
        ("建议用时", "按工作日每天约30分钟估算，仅供参考；大部头可以只读推荐的章节。"),
        ("记录方式", "「总书单」的状态列下拉选择 未开始/在读/已读/搁置，「读者」列选择爸爸/妈妈/爸妈都读，再填日期、评分和笔记；"
                     f"「亲子共读」里{'、'.join(KID_READERS)}各占一列，同一本书各记各的进度；下方统计会自动更新。"),
    ]
    # 写在前面（放在最前）：每条要点占一行，分类名只写在第一行
    pre = []
    for title, _, a, k in preface():
        items = [("成人", x) for x in a] + [("亲子", x) for x in k]
        pre += [(title if i == 0 else "", f"【{who}】{lead}：{text}") for i, (who, (lead, text)) in enumerate(items)]
    guide = pre + guide
    for k, v in guide:
        ws.cell(row=r, column=1, value=k).font = Font(bold=True)
        ws.cell(row=r, column=2, value=v).alignment = WRAP
        ws.merge_cells(start_row=r, start_column=2, end_row=r, end_column=5)
        ws.row_dimensions[r].height = max(32, row_height([v], [54]))
        r += 1

    r += 1
    status = f"总书单!${main_col['状态']}$2:${main_col['状态']}${len(rows) + 1}"
    phase_rng = f"总书单!${main_col['阅读阶段']}$2:${main_col['阅读阶段']}${len(rows) + 1}"
    domain_rng = f"总书单!${main_col['领域']}$2:${main_col['领域']}${len(rows) + 1}"
    theme_rng = f"总书单!${main_col['主题']}$2:${main_col['主题']}${len(rows) + 1}"
    title_rng = f"总书单!${main_col['书名']}$2:${main_col['书名']}${len(rows) + 1}"
    reader_rng = f"总书单!${main_col['读者']}$2:${main_col['读者']}${len(rows) + 1}"

    def table(title, first_col, keys, counts):
        """counts(key, row) 返回该行的 (总数, 已读, 在读) 公式。"""
        nonlocal r
        ws.cell(row=r, column=1, value=title).font = Font(bold=True, size=13, color="1F3864")
        r += 1
        for c, h in enumerate([first_col, "总数", "已读", "在读", "完成率"], 1):
            cell = ws.cell(row=r, column=c, value=h)
            cell.fill, cell.font, cell.alignment, cell.border = HEADER_FILL, HEADER_FONT, CENTER, BORDER
        r += 1
        for key in keys:
            ws.cell(row=r, column=1, value=key)
            for c, v in enumerate(counts(key, r), 2):
                ws.cell(row=r, column=c, value=v)
            ws.cell(row=r, column=5, value=f"=IF(B{r}=0,0,C{r}/B{r})").number_format = "0%"
            for c in range(1, 6):
                ws.cell(row=r, column=c).border = BORDER
                ws.cell(row=r, column=c).alignment = CENTER
            r += 1
        r += 1

    def grouped(rng):
        return lambda key, row: (f'=COUNTIF({rng},A{row})', f'=COUNTIFS({rng},A{row},{status},"已读")',
                                 f'=COUNTIFS({rng},A{row},{status},"在读")')

    def kid_counts(name, row):
        letter = get_column_letter(KIDS_HEADERS.index(name) + 1)
        rng = f"亲子共读!${letter}$2:${letter}${len(KIDS) + 1}"
        return len(KIDS), f'=COUNTIF({rng},"已读")', f'=COUNTIF({rng},"在读")'

    table("总体进度", "范围", ["全部书目"],
          lambda key, row: (f"=COUNTA({title_rng})", f'=COUNTIF({status},"已读")', f'=COUNTIF({status},"在读")'))
    table("按读者进度（成人书单）", "读者", ["爸爸", "妈妈", "爸妈都读"], grouped(reader_rng))
    table("亲子共读进度", "读者", KID_READERS, kid_counts)
    table("按阶段进度", "阅读阶段", [PHASES[p][0] for p in (1, 2, 3, 4, 0)], grouped(phase_rng))
    table("按主题进度", "主题", [t for t, *_ in THEMES], grouped(theme_rng))
    table("按领域进度", "领域", list(BOOKS.keys()), grouped(domain_rng))


def write_csv(rows):
    with open(os.path.join(OUT_DIR, "人类智慧经典书单.csv"), "w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f)
        w.writerow(MAIN_HEADERS)
        for r in rows:
            vals = [r.get(h, "") for h in MAIN_HEADERS]
            vals[MAIN_HEADERS.index("状态")] = "未开始"
            w.writerow(["" if v is None else v for v in vals])
    with open(os.path.join(OUT_DIR, "亲子共读书单.csv"), "w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f)
        w.writerow(KIDS_HEADERS)
        for i, k in enumerate(KIDS, 1):
            w.writerow([f"K{i:03d}", k[0], kid_title(k[1]), *k[2:], MEDIA.get(k[1], ""), kid_level(k[1]),
                        TEXTBOOK_GRADE.get(k[1], ""), *[""] * len(KID_READERS)])


def md_cell(v):
    return "" if v is None else str(v).replace("|", "｜").replace("\n", " ")


def md_table(headers, rows):
    lines = ["| " + " | ".join(headers) + " |", "|" + "|".join(["---"] * len(headers)) + "|"]
    lines += ["| " + " | ".join(md_cell(v) for v in row) + " |" for row in rows]
    return "\n".join(lines)


def stars(n):
    return "★" * n + "☆" * (5 - n)


def year_table():
    return md_table(["月份", "大人读", "孩子读（按年龄）", "一起做", "饭桌上聊"],
                    [[f"**{m}月**<br>{theme}", f"《{adult}》", "<br>".join(f"{tier}《{t}》" for tier, t in zip(YEAR_TIERS, kids)),
                      todo, "<br>".join(f"{n} {q}" for n, q in zip("①②③", questions))]
                     for m, theme, adult, kids, todo, questions in YEAR_PLAN])


def media_table(titles):
    return md_table(["书", "对照看"], [[f"《{t}》", MEDIA[t]] for t in titles])


def theme_table(rows):
    """八大主题速查：主题｜包含的领域｜本数｜从这本开始。"""
    table = []
    for theme, emoji, ds, first in THEMES:
        n = sum(1 for r in rows if r["主题"] == theme)
        table.append([f"{emoji} **{theme}**", "、".join(ds),
                      f"{n}" + (f"（另有亲子共读 {len(KIDS)} 本）" if theme == KIDS_THEME else ""), f"《{first}》"])
    return md_table(["主题", "包含的领域", "本数", "从这本开始"], table)


def kid_must_line(band):
    ts = KID_MUST.get(band, [])
    return f"{MUST_MARK} **先读这 {len(ts)} 本**：" + "".join(f"《{t}》" for t in ts) if ts else ""


def write_markdown(rows):
    plan = phase_plan(rows)
    must = [r for r in rows if r["级别"] == "必读"]
    out = [
        "# 人类智慧经典书单",
        "",
        f"> 成人主书单 **{len(rows)}** 本 · **{len(BOOKS)}** 个领域 · 4 个阶段＋随时选读 · 必读 **{len(must)}** 本 · "
        f"亲子共读 **{len(KIDS)}** 本",
        "",
        "## 目录",
        "",
        "- [写在前面：怎么挑、怎么分、怎么读](#写在前面怎么挑怎么分怎么读)",
        "- [使用说明](#使用说明)",
        "- [一、必读速查](#一必读速查)",
        "- [二、年度 12 本：每月一本，全家同读](#二年度-12-本每月一本全家同读)",
        "- [三、五年阅读路线](#三五年阅读路线)",
        "- [四、分领域总书单](#四分领域总书单)",
        "- [五、亲子共读书单](#五亲子共读书单)",
        "",
        "## 写在前面：怎么挑、怎么分、怎么读",
        "",
        *preface_md(),
        "## 使用说明",
        "",
        f"- **级别**：{LEVEL_NOTE}",
        f"- **内容定位**：{POSITION_NOTE}",
        "- **难度**：★ 轻松好读 · ★★ 普通 · ★★★ 需要专注 · ★★★★ 需要导读或注释 · ★★★★★ 硬核巨著。",
        "- **阶段**：①入门筑基 → ②经典核心 → ③深入精读 → ④高峰攻坚；" + ANYTIME_NOTE,
        f"- **三线并行**：{THREE_LINES}",
        f"- **{TEXTBOOK_MARK} 课内必读**：孩子语文课要读的书都并入了第五节亲子共读，书名后的{TEXTBOOK_MARK}标出年级。",
        "- **建议用时**：按工作日每天约 30 分钟估算，仅供参考；大部头可以只读推荐章节。",
        "- **译本**：推荐译本为常见口碑版本，购买前请在购书平台确认具体版次。",
        f"- **🪜 读不动？先读**：{len(BRIDGE)} 本大部头配了一本更薄的入门书，写在“阅读建议”后面。",
        f"- **📺 影视/纪录片**：{len(MEDIA)} 本书配了确实存在的电影、剧集或纪录片。{MEDIA_NOTE}",
        "",
        "## 一、必读速查",
        "",
        f"时间有限时，先读这 {len(must)} 本。",
        "",
        md_table(["书名", "作者", "领域", "一句话", "阶段"],
                 [[book_title(r["书名"]), r["作者"], r["领域"], r["核心智慧"], r["阅读阶段"]] for r in must]),
        "",
        "## 二、年度 12 本：每月一本，全家同读",
        "",
        YEAR_NOTE,
        "",
        year_table(),
        "",
        "## 三、五年阅读路线",
        "",
    ]
    for phase, summary, items in plan:
        name, span, goal = PHASES[phase]
        out += [f"### {name}（{span}）", "", f"> {summary.split('｜', 2)[2]}", ""]
        if phase:
            out.append(md_table(
                ["序号", "书名", "作者", "并行线", "用时(周)", "本线累计(周)", "难度", "级别"],
                [[i, book_title(b["书名"]), b["作者"], line, b["建议用时(周)"], run, stars(b["难度(1-5)"]), b["级别"]]
                 for i, (b, line, run) in enumerate(items, 1)]))
        else:
            for group, desc, _ in ANYTIME_GROUPS:
                gb = [b for b, g, _ in items if g == group]
                out += [f"#### {group}（{len(gb)} 本）", "", desc, "", md_table(
                    ["序号", "书名", "作者", "领域", "用时(周)", "难度", "级别"],
                    [[i, book_title(b["书名"], PICK_MARK if b["书名"] in ANYTIME_PICKS else ""), b["作者"], b["领域"],
                      b["建议用时(周)"], stars(b["难度(1-5)"]), b["级别"]]
                     for i, b in enumerate(gb, 1)]), ""]
        out.append("")

    out += ["## 四、分领域总书单", "", THEME_NOTE, "", theme_table(rows), ""]
    for di, domain in enumerate(BOOKS, 1):
        books = [r for r in rows if r["领域"] == domain]
        out += [f"### {di}. {domain}（{len(books)} 本）", ""]
        out.append(md_table(
            ["编号", "书名", "作者", "年代", "核心智慧", "难度", "级别", "内容定位", "阶段", "推荐版本/译本", "阅读建议", "影视/纪录片"],
            [[r["编号"], book_title(r["书名"], PICK_MARK if r["书名"] in ANYTIME_PICKS else ""), r["作者"], r["成书年代"],
              r["核心智慧"], stars(r["难度(1-5)"]),
              r["级别"], r["内容定位"], r["阅读阶段"], r["推荐版本/译本"],
              r["阅读建议"] + (f"<br>🪜 读不动？先读{r['读不动？先读']}" if r["读不动？先读"] else ""),
              r["影视/纪录片"]] for r in books]))
        out.append("")

    out += ["## 五、亲子共读书单", "",
            "> 年龄只是参考，孩子感兴趣就可以提前读；大部分书都配了英文版或双语资源；“长大后接着读”指向主书单里的成人经典；"
            f"书名带{MUST_MARK}的是必读（每个年龄段 5 本、每个专题 2–3 本，共 {len(KID_MUST_TITLES)} 本），"
            f"带{FAMILY_MARK}的适合全家一起读，带{TEXTBOOK_MARK}的是语文课内必读并标了年级。{TEXTBOOK_NOTE}", ""]
    for band, note in KID_BANDS:
        ks = [k for k in KIDS if k[0] == band]
        out += [f"### {band}（{len(ks)} 本）", "", f"> {note}", "", kid_must_line(band), ""]
        out.append(md_table(
            ["书名", "作者/来源", "中文版本", "英文版/双语", "阅读年龄", "共读玩法", "长大后接着读", "影视/纪录片"],
            [[kid_title(k[1], grade=True), *k[2:], MEDIA.get(k[1], "")] for k in ks]))
        out.append("")

    path = os.path.join(OUT_DIR, "人类智慧经典书单.md")
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(out))
    return path


