        f"- **亲子书单按年龄、接得上课本**：按孩子的年龄分段，标出统编语文教材要求读的 {len(TEXTBOOK_GRADE)} 本；"
        "每本书都写了一种一起读的玩法，以及长大后可以接着读的成人经典。",
        "- **不收 AI 类的书**：这个领域变化太快，今天的畅销书明年可能就过时了；"
