        "",
        "## 书单一览",
        "",
        f"- 📖 **给大人：{len(rows)} 本人类智慧经典**。{len(THEMES)} 个主题、{len(BOOKS)} 个领域，从《论语》《史记》读到《人类简史》《纳瓦尔宝典》。",
        f"- 🧸 **给孩子：{len(KIDS)} 本亲子共读**。4 个年龄段加 {len(topics)} 个专题（{'、'.join(topics)}），"
        "从 3 岁的绘本一直读到初中的名著。",
        f"- 🏷️ **书里的标记**：{MUST_MARK} 必读（成人 {must} 本、亲子 {len(KID_MUST_TITLES)} 本）· "
        f"{REC_MARK} 推荐（共 {rec} 本）· {FAMILY_MARK} 全家共读 · {TEXTBOOK_MARK} 课内必读（后面标了年级）。没有标记的是拓展。",
