# 远山三叠，与网页卷首同一组曲线（坐标系 1440×150）：起点 + 每三点一段三次贝塞尔
HILLS = [
    (0.08, [(0, 92), (120, 70), (220, 40), (340, 52), (460, 64), (520, 18), (660, 14), (800, 10), (860, 66), (1000, 58),
            (1140, 50), (1240, 8), (1440, 20)]),
    (0.16, [(0, 116), (140, 96), (260, 84), (380, 92), (500, 100), (580, 56), (720, 52), (860, 48), (940, 92), (1080, 86),
            (1220, 80), (1320, 60), (1440, 64)]),
    (1.0, [(0, 132), (160, 118), (300, 108), (440, 114), (580, 120), (680, 96), (820, 98), (960, 100), (1060, 122),
           (1200, 116), (1300, 112), (1380, 104), (1440, 106)]),
]
# 卷首云月，与网页 svg.moon 同一组坐标（240×170，月心 130,74，半径 46）：每朵云是（闭合轮廓, 描边不透明度, 云尾线）
MOON_CLOUDS = [
    ([(44, 124), (44, 110), (62, 104), (72, 112), (76, 96), (100, 94), (108, 108), (114, 100), (130, 102), (132, 114),
      (142, 110), (156, 114), (156, 124)], 0.75,
     [[(156, 124), (212, 124)], [(44, 124), (30, 124), (30, 124), (30, 124), (20, 124), (18, 114), (26, 112), (31, 111),
                                 (33, 116), (30, 118)]]),
    ([(168, 56), (168, 46), (178, 42), (184, 47), (188, 38), (202, 39), (204, 48), (212, 46), (220, 50), (220, 56)], 0.6,
     [[(220, 56), (234, 56)], [(160, 56), (168, 56)]]),
]


def bezier_path(pts, steps=24):
    """起点 + 每三点一段三次贝塞尔；只有两点时就是直线。返回采样后的折线点。"""
    if len(pts) == 2:
        return list(pts)
    curve = [pts[0]]
    for i in range(1, len(pts) - 1, 3):
        p0, p1, p2, p3 = curve[-1], pts[i], pts[i + 1], pts[i + 2]
        for n in range(1, steps + 1):
            t = n / steps
            curve.append(tuple((1 - t) ** 3 * p0[j] + 3 * (1 - t) ** 2 * t * p1[j] + 3 * (1 - t) * t * t * p2[j]
                               + t ** 3 * p3[j] for j in range(2)))
    return curve


def write_full_poster(rows):
    """完整书单海报「开卷有益」：成人按主题、领域，亲子按年龄段和专题，每组三列只列书名。
    卷首与网页同款：墨色底、鎏金立体大字、云月与远山，卷首右下角署名加印章；卷尾远山倒挂，引导关注公众号。
    出两版：带公众号二维码的（公众号、朋友圈、微信群），只写公众号名的（小红书等不便放二维码的平台）。
    缺少 Pillow 或中文字体时跳过；缺少公众号二维码图片时两版都只写公众号名。返回两版的路径。"""
    try:
        from PIL import Image, ImageChops, ImageDraw, ImageFilter, ImageFont
    except ImportError:
        return None
    fonts = next((f for f in FULL_POSTER_FONTS if os.path.exists(f[0]) and os.path.exists(f[2])), None)
    if fonts is None:
        return None

    def font(size, bold=False):
        return ImageFont.truetype(fonts[2] if bold else fonts[0], size, index=fonts[3] if bold else fonts[1])

    # 书名用宋体黑（Songti.ttc 第 0 个字形），没有就用粗体
    def font_black(size):
        return ImageFont.truetype(fonts[0], size, index=0) if fonts[0].endswith("Songti.ttc") else font(size, True)

    ink, ink2, paper, card, rule = "#1B2838", "#2A3D52", "#F5F0E6", "#FFFDF8", "#E4DACA"
    cinnabar, gold, gold2, jade, grey = "#B23A2E", "#C29A4A", "#E3C27A", "#4F7A6A", "#A39A8A"
    text, ext_text, muted = "#2B2620", "#6B6255", "#8A7F6E"
    level_style = {"必读": (cinnabar, True, ink), "推荐": (gold, False, text), "拓展": (grey, False, ext_text)}
    W, M, PAD, COLS, CGAP, LH = 1242, 56, 32, 3, 18, 40
    col_w = (W - 2 * M - 2 * PAD - (COLS - 1) * CGAP) // COLS
    img = Image.new("RGB", (W, 22000), paper)
    d = ImageDraw.Draw(img)

    # 宣纸底纹：两层错开的淡赭色细点，和网页背景一致
    for step, (ox, oy), color in ((22, (0, 0), (239, 232, 220)), (13, (7, 9), (241, 235, 225))):
        for yy in range(oy, img.height, step):
            for xx in range(ox, W, step):
                d.rectangle([xx, yy, xx + 1, yy + 1], fill=color)

    def hex_rgb(c):
        return tuple(int(c[i:i + 2], 16) for i in (1, 3, 5))

    def spaced(x, y, s, f, fill, gap, draw=None):
        draw = draw or d
        for ch in s:
            draw.text((x, y), ch, font=f, fill=fill)
            x += draw.textlength(ch, font=f) + gap
        return x

    def spaced_w(s, f, gap):
        return sum(d.textlength(ch, font=f) for ch in s) + gap * (len(s) - 1)

    def wrap(s, f, width):
        """中文按字、英文按词折行，避免把 Reading 这样的单词拆成两半。"""
        lines, cur = [], ""
        for tok in re.findall(r"[A-Za-z0-9&'.\-]+|\s+|.", s):
            if cur and tok[0] not in NO_LINE_START and d.textlength(cur + tok, font=f) > width:
                lines.append(cur.rstrip())
                cur = tok.lstrip()
            else:
                cur += tok
        lines = lines + [cur] if cur else lines
        # 末行只剩一个字时，从上一行借一个字下来，避免孤字成行
        if len(lines) > 1 and len(lines[-1]) == 1 and not lines[-2][-1].isascii():
            lines[-2:] = [lines[-2][:-1], lines[-2][-1] + lines[-1]]
        return lines

    def ink_panel(h):
        """墨色横向渐变底板（RGBA），卷首卷尾共用。"""
        a, b = hex_rgb(ink), hex_rgb(ink2)
        row = Image.new("RGB", (W, 1))
        row.putdata([tuple(round(a[k] + (b[k] - a[k]) * x / (W - 1)) for k in range(3)) for x in range(W)])
        return row.resize((W, h)).convert("RGBA")

    def hills(panel, top, height, flip=False):
        """在底板上画远山：后两叠半透明宣纸色，最前一叠直接挖空，露出底下带底纹的正文纸面。
        flip=True 时山倒挂在底板顶部（卷尾用）。四倍超采样画蒙版，山脊线是平滑的。"""
        k = 4
        sx, sy = W * k / 1440, height * k / 150
        for alpha, pts in HILLS:
            poly = [(x * sx, (150 - y if flip else y) * sy) for x, y in bezier_path(pts)]
            poly += [(W * k, 0), (0, 0)] if flip else [(W * k, height * k), (0, height * k)]
            m = Image.new("L", (W * k, height * k), 0)
            ImageDraw.Draw(m).polygon(poly, fill=255)
            m = m.resize((W, height), Image.LANCZOS)
            if alpha < 1:
                panel.paste(paper, (0, top, W, top + height), m.point(lambda v: round(v * alpha)))
            else:
                region = panel.crop((0, top, W, top + height))
                region.putalpha(ImageChops.subtract(region.getchannel("A"), m))
                panel.paste(region, (0, top))

    def moon(panel, ox, oy, s):
        """云月：金色光晕 → 由亮到暗的月面和淡淡月影 → 与夜空同色、金线描边的祥云。
        (ox, oy) 是网页 svg 坐标原点在底板上的位置，s 为缩放倍数；只在 240×170 的画幅内四倍超采样。"""
        cx, cy, r = ox + 130 * s, oy + 74 * s, 46 * s
        glow = Image.new("L", panel.size, 0)
        ImageDraw.Draw(glow).ellipse([cx - r * 1.45, cy - r * 1.45, cx + r * 1.45, cy + r * 1.45], fill=70)
        panel.paste(gold2, (0, 0), glow.filter(ImageFilter.GaussianBlur(r * 0.35)))
        k = 4
        size = (round(240 * s), round(170 * s))
        layer = Image.new("RGBA", (size[0] * k, size[1] * k), (0, 0, 0, 0))
        ld = ImageDraw.Draw(layer)

        def at(x, y):
            return x * s * k, y * s * k

        R, (CX, CY) = r * k, at(130, 74)
        stops = [(0, (255, 248, 230)), (0.55, (243, 217, 154)), (1, (201, 155, 69))]
        for n in range(round(R), 0, -2):
            t = n / R
            (t0, c0), (t1, c1) = next((stops[i], stops[i + 1]) for i in range(2) if t <= stops[i + 1][0])
            c = tuple(round(c0[j] + (c1[j] - c0[j]) * (t - t0) / (t1 - t0)) for j in range(3))
            off = (1 - t) * R * -0.28
            ld.ellipse([CX - n + off, CY - n + off, CX + n + off, CY + n + off], fill=c + (235,))
        shade = Image.new("RGBA", layer.size, (0, 0, 0, 0))
        for x, y, rr, a in ((114, 62, 9, 30), (146, 90, 6, 26), (140, 56, 4, 26)):
            (X, Y), RR = at(x, y), rr * s * k
            ImageDraw.Draw(shade).ellipse([X - RR, Y - RR, X + RR, Y + RR], fill=(184, 138, 58, a))
        layer.alpha_composite(shade)
        sky, line_w = hex_rgb("#283A4F"), max(2, round(1.4 * s * k))
        for outline, alpha, tails in MOON_CLOUDS:
            pts = [at(x, y) for x, y in bezier_path(outline)]
            ld.polygon(pts, fill=sky + (255,))
            ld.line(pts + pts[:1], fill=hex_rgb(gold2) + (round(255 * alpha),), width=line_w, joint="curve")
            for tail in tails:
                ld.line([at(x, y) for x, y in bezier_path(tail)], fill=hex_rgb(gold2) + (round(255 * alpha * 0.66),),
                        width=line_w, joint="curve")
        panel.alpha_composite(layer.resize(size, Image.LANCZOS), (ox, oy))

    def gilt(panel, x, y, s, f, gap):
        """鎏金立体字：投影 → 由浅到深的金色叠出厚度 → 顶面竖向金色渐变。"""
        m = Image.new("L", panel.size, 0)
        spaced(x, y, s, f, 255, gap, ImageDraw.Draw(m))
        shadow = Image.new("L", panel.size, 0)
        shadow.paste(m, (0, 18))
        panel.paste((0, 0, 0), (0, 0), shadow.filter(ImageFilter.GaussianBlur(16)).point(lambda v: round(v * 0.55)))
        for i, c in zip(range(6, 0, -1), ("#3E2D12", "#4A3616", "#5A421B", "#6E5222", "#7F5F28", "#8C6A2C")):
            layer = Image.new("L", panel.size, 0)
            layer.paste(m, (0, i))
            panel.paste(c, (0, 0), layer)
        top, bottom = m.getbbox()[1], m.getbbox()[3]
        stops = [(0, (255, 248, 230)), (0.45, (243, 217, 154)), (1, (201, 155, 69))]
        grad = Image.new("RGB", (1, panel.height))
        px = []
        for yy in range(panel.height):
            t = min(max((yy - top) / max(bottom - top, 1), 0), 1)
            (t0, c0), (t1, c1) = next((stops[i], stops[i + 1]) for i in range(len(stops) - 1) if t <= stops[i + 1][0])
            u = (t - t0) / (t1 - t0)
            px.append(tuple(round(c0[j] + (c1[j] - c0[j]) * u) for j in range(3)))
        grad.putdata(px)
        panel.paste(grad.resize(panel.size), (0, 0), m)

    def soft_shadow(box, radius, blur=16, dy=8, alpha=34):
        x0, y0, x1, y1 = box
        p = blur * 3
        m = Image.new("L", (x1 - x0 + 2 * p, y1 - y0 + 2 * p), 0)
        ImageDraw.Draw(m).rounded_rectangle([p, p, p + x1 - x0, p + y1 - y0], radius=radius, fill=alpha)
        m = m.filter(ImageFilter.GaussianBlur(blur))
        img.paste((90, 64, 24), (x0 - p, y0 - p + dy, x1 + p, y1 + p + dy), m)

    def dot(x, y, color, r=5):
        d.ellipse([x - r, y - r, x + r, y + r], fill=color)

    def seal(draw, x, y, S, name):
        """四字朱砂方印：按印文习惯从右列读起，右列上下两字、左列上下两字。"""
        draw.rounded_rectangle([x, y, x + S, y + S], radius=8, fill=cinnabar)
        draw.rounded_rectangle([x + 5, y + 5, x + S - 5, y + S - 5], radius=5, outline="#F3D9C8", width=1)
        f, half = font(round(S * 0.36), True), (S - 10) / 2
        for i, ch in enumerate(name[:4]):
            cx, cy = x + 5 + half * (1.5 if i < 2 else 0.5), y + 5 + half * (0.5 if i % 2 == 0 else 1.5)
            l, t, r, b = draw.textbbox((0, 0), ch, font=f)
            draw.text((cx - (l + r) / 2, cy - (t + b) / 2), ch, font=f, fill=paper)

    # ---------- 卷首 ----------
    H, HILL_H = 850, 170
    head = ink_panel(H)
    hp = ImageDraw.Draw(head)
    moon(head, W - M - 300, 70, 1.25)
    f_kicker = font(26)
    hp.line([M, 92, M + 44, 92], fill=gold, width=2)
    spaced(M + 60, 76, "人类智慧经典书单", f_kicker, gold2, 8, hp)
    gilt(head, M - 6, 118, "开卷有益", font_black(156), 34)
    hp.text((M, 336), "一份够读一辈子的经典书单 —— 从源头经典到当代实用，给大人，也给孩子", font=font(28), fill="#D6D0C4")
    stats = [(len(rows), "成人书单 · 本"), (len(BOOKS), f"领域 · {len(THEMES)} 大分类"),
             (len(KIDS), "亲子共读 · 本"), (len(KID_BANDS) - 4, "亲子专题 · 4 档年龄")]
    sw, sgap, sy0, sh = (W - 2 * M - 3 * 18) // 4, 18, 404, 112
    for i, (n, label) in enumerate(stats):
        x0 = M + i * (sw + sgap)
        box = Image.new("RGBA", (sw, sh), (0, 0, 0, 0))
        ImageDraw.Draw(box).rounded_rectangle([0, 0, sw - 1, sh - 1], radius=16, fill=(255, 255, 255, 16),
                                              outline=hex_rgb(gold2) + ((235,) if i == 0 else (80,)), width=2)
        head.alpha_composite(box, (x0, sy0))
        hp.text((x0 + 24, sy0 + 12), str(n), font=font(54, True), fill="#FFF8E6")
        hp.text((x0 + 24, sy0 + 74), label, font=font(22), fill="#A9ACB2")
    hp.rectangle([M, 566, M + 4, 646], fill=gold)
    hp.text((M + 24, 568), "读书破万卷，下笔如有神。", font=font(30), fill="#E6E0D4")
    hp.text((M + 24, 614), "—— 杜甫《奉赠韦左丞丈二十二韵》", font=font(22), fill="#8E97A6")
    # 署名：右下角两行小字配一方朱印，图被截图转发也带着出处
    S = 84
    seal(hp, W - M - S, 564, S, WECHAT_NAME)
    for s, f, color, yy in (("编选整理", font(22), "#8E97A6", 572), (f"公众号 · {WECHAT_NAME}", font(28), "#E6E0D4", 606)):
        hp.text((W - M - S - 22 - hp.textlength(s, font=f), yy), s, font=f, fill=color)
    hills(head, H - HILL_H, HILL_H)
    img.paste(head, (0, 0), head)

    # 图例：一条小签条
    y = H + 6
    f_leg = font(24)
    legend = [("必读", cinnabar), ("推荐", gold), ("拓展", grey)]
    note = "亲子共读：红点为必读，小字为适读年龄"
    lw = sum(22 + d.textlength(s, font=f_leg) + 36 for s, _ in legend) + 30 + d.textlength(note, font=f_leg)
    lx = (W - lw) / 2
    d.rounded_rectangle([lx - 30, y, lx + lw + 30, y + 52], radius=26, fill=card, outline=rule, width=1)
    x = lx
    for label, color in legend:
        dot(x + 6, y + 26, color, 6)
        d.text((x + 22, y + 11), label, font=f_leg, fill=text)
        x += 22 + d.textlength(label, font=f_leg) + 36
    d.line([x - 6, y + 14, x - 6, y + 38], fill=rule, width=2)
    d.text((x + 24, y + 11), note, font=f_leg, fill=muted)
    y += 112

    def part(y, no, name, sub):
        """篇章标题：朱砂方印写序号，宋体大字写篇名。"""
        S = 72
        d.rounded_rectangle([M, y, M + S, y + S], radius=10, fill=cinnabar)
        d.rounded_rectangle([M + 6, y + 6, M + S - 6, y + S - 6], radius=6, outline="#F3D9C8", width=1)
        f_no = font(42, True)
        l, t, r, b = d.textbbox((0, 0), no, font=f_no)
        d.text((M + (S - r - l) / 2, y + (S - b - t) / 2), no, font=f_no, fill=paper)
        x = spaced(M + S + 24, y + 6, name, font(52, True), ink, 10)
        d.text((x + 16, y + 28), sub, font=font(26), fill=muted)
        return y + S + 44

    def theme_head(y, name, n):
        f_name, f_n = font(38, True), font(24)
        count = f"{n} 本"
        tw = spaced_w(name, f_name, 8) + 16 + d.textlength(count, font=f_n)
        x0 = (W - tw) / 2
        for xa, xb, ra, rb in ((M, x0 - 52, rule, gold), (x0 + tw + 52, W - M, gold, rule)):
            # 两侧细线由淡到金，向标题收拢
            ca, cb = hex_rgb(ra), hex_rgb(rb)
            steps = 40
            for s in range(steps):
                c = tuple(round(ca[j] + (cb[j] - ca[j]) * s / (steps - 1)) for j in range(3))
                d.line([xa + (xb - xa) * s / steps, y + 27, xa + (xb - xa) * (s + 1) / steps, y + 27], fill=c, width=2)
        for cx in (x0 - 32, x0 + tw + 32):
            d.polygon([(cx, y + 18), (cx + 9, y + 27), (cx, y + 36), (cx - 9, y + 27)], fill=gold)
            d.polygon([(cx, y + 23), (cx + 4, y + 27), (cx, y + 31), (cx - 4, y + 27)], fill=paper)
        x = spaced(x0, y, name, f_name, ink, 8)
        d.text((x + 16, y + 12), count, font=f_n, fill=muted)
        return y + 84

    def group(y, title, items):
        """一组书一张卡片：标题 + 三列书名。items 为 (书名, 圆点颜色, 是否加粗, 文字颜色, 小字)。"""
        f_t, f_tb, f_s = font(25), font(25, True), font(19)
        inner = col_w - 22
        cells = []
        for t, color, bold, fill, sub in items:
            ft = f_tb if bold else f_t
            lines = wrap(t, ft, inner)
            inline = bool(sub) and d.textlength(lines[-1], font=ft) + 10 + d.textlength(sub, font=f_s) <= inner
            cells.append((lines, ft, color, fill, sub, inline, len(lines) * LH + (26 if sub and not inline else 0)))
        grid = [cells[i:i + COLS] for i in range(0, len(cells), COLS)]
        body = sum(max(c[-1] for c in row) + 6 for row in grid)
        head_h = 74
        card_h = PAD + head_h + body + PAD - 12
        soft_shadow((M, y, W - M, y + card_h), 18)
        d.rounded_rectangle([M, y, W - M, y + card_h], radius=18, fill=card, outline=rule, width=1)
        d.rounded_rectangle([M + PAD, y + PAD + 6, M + PAD + 5, y + PAD + 36], radius=2, fill=cinnabar)
        f_g, f_n = font(30, True), font(22)
        d.text((M + PAD + 18, y + PAD), title, font=f_g, fill=jade)
        d.text((M + PAD + 18 + d.textlength(title, font=f_g) + 14, y + PAD + 8), f"{len(items)} 本", font=f_n, fill=muted)
        # 标题下的分隔线用虚线，像书页里的界栏
        ly_ = y + PAD + 56
        for xx in range(M + PAD, W - M - PAD, 10):
            d.line([xx, ly_, min(xx + 5, W - M - PAD), ly_], fill=rule, width=1)
        cy = y + PAD + head_h
        for row in grid:
            for j, (lines, ft, color, fill, sub, inline, _) in enumerate(row):
                x = M + PAD + j * (col_w + CGAP)
                dot(x + 5, cy + 17, color)
                ly = cy
                for line in lines:
                    d.text((x + 22, ly), line, font=ft, fill=fill)
                    ly += LH
                if sub:
                    sx_ = x + 22 + d.textlength(lines[-1], font=ft) + 10 if inline else x + 22
                    d.text((sx_, ly - LH + 6 if inline else ly - 4), sub, font=f_s, fill=grey)
            cy += max(c[-1] for c in row) + 6
        return y + card_h + 26

    y = part(y, "壹", "成人书单", f"{len(THEMES)} 个主题 · {len(BOOKS)} 个领域 · {len(rows)} 本")
    for theme, _, domains, _ in THEMES:
        y = theme_head(y, theme, sum(1 for r in rows if r["主题"] == theme))
        for domain in domains:
            items = [(r["书名"], *level_style[r["级别"]], "") for r in rows if r["领域"] == domain]
            y = group(y, domain, items)
        y += 22

    y = part(y + 24, "贰", "亲子共读", f"4 个年龄段 · {len(KID_BANDS) - 4} 个专题 · {len(KIDS)} 本")
    for band, _ in KID_BANDS:
        items = [(k[1], *((cinnabar, True, ink) if k[1] in KID_MUST_TITLES else (grey, False, text)), k[5])
                 for k in KIDS if k[0] == band]
        y = group(y, band.replace("｜", " · "), items)

    # ---------- 卷尾：远山倒挂，引导关注公众号、回复关键词领取完整版 ----------
    y += 10
    FHILL = 150
    gifts = ["可打印的 Excel 完整版", "每本书的推荐版本与读法", "高清长图与网页版"]
    qr_img = Image.open(WECHAT_QR).convert("RGB") if os.path.exists(WECHAT_QR) else None

    def kicker(draw, x, y, s, center=False):
        f = font(24)
        w = spaced_w(s, f, 8)
        x = (W - w) / 2 if center else x + 58
        draw.line([x - 58, y + 13, x - 14, y + 13], fill=gold, width=2)
        if center:
            draw.line([x + w + 14, y + 13, x + w + 58, y + 13], fill=gold, width=2)
        spaced(x, y, s, f, gold2, 8, draw)

    def footer(with_qr):
        foot = ink_panel(700)
        fp = ImageDraw.Draw(foot)
        hills(foot, 0, FHILL, flip=True)
        f_name, f_ask, f_gift = font_black(64), font(30), font(25)
        ask = f"回复「{WECHAT_KEYWORD}」，领取："
        if with_qr:
            # 左边二维码（自带白边和头像），右边一列引导文字，整块竖向对齐二维码中线
            qs = 300
            qx, qy = M + 30, FHILL + 56
            fp.rounded_rectangle([qx - 10, qy - 10, qx + qs + 10, qy + qs + 10], radius=18, fill="white", outline=gold, width=3)
            foot.paste(qr_img.resize((qs, qs), Image.LANCZOS), (qx, qy))
            tx = qx + qs + 74
            ty = qy + (qs - 300) // 2
            kicker(fp, tx, ty, "长按识别 · 关注公众号")
            spaced(tx, ty + 42, WECHAT_NAME, f_name, "#FFF8E6", 12, fp)
            fp.text((tx, ty + 132), ask, font=f_ask, fill=gold2)
            for i, s in enumerate(gifts):
                dot_y = ty + 196 + i * 38
                fp.ellipse([tx + 2, dot_y + 9, tx + 10, dot_y + 17], fill=gold)
                fp.text((tx + 24, dot_y), s, font=f_gift, fill="#C9C4BA")
            motto_y = qy + qs + 64
        else:
            # 不放二维码：居中写公众号名，读者自己去微信里搜
            ty = FHILL + 44
            kicker(fp, 0, ty, "微信搜索公众号", center=True)
            nw = spaced_w(WECHAT_NAME, f_name, 16)
            spaced((W - nw) / 2, ty + 44, WECHAT_NAME, f_name, "#FFF8E6", 16, fp)
            fp.text(((W - fp.textlength(ask, font=f_ask)) / 2, ty + 138), ask, font=f_ask, fill=gold2)
            s = " · ".join(gifts)
            fp.text(((W - fp.textlength(s, font=f_gift)) / 2, ty + 192), s, font=f_gift, fill="#C9C4BA")
            motto_y = ty + 270
        f_m = font(24)
        motto = "书山有路勤为径 · 学海无涯苦作舟"
        mw = spaced_w(motto, f_m, 6)
        spaced((W - mw) / 2, motto_y, motto, f_m, "#8E97A6", 6, fp)
        for xa, xb in (((W - mw) / 2 - 90, (W - mw) / 2 - 24), ((W + mw) / 2 + 24, (W + mw) / 2 + 90)):
            fp.line([xa, motto_y + 14, xb, motto_y + 14], fill=gold, width=1)
        return foot.crop((0, 0, W, motto_y + 80))

    paths = []
    for with_qr, name in ((qr_img is not None, "开卷有益-完整书单海报.png"), (False, "开卷有益-完整书单海报-无二维码.png")):
        foot = footer(with_qr)
        out = img.crop((0, 0, W, y + foot.height))
        out.paste(foot, (0, y), foot)
        paths.append(os.path.join(OUT_DIR, name))
        out.save(paths[-1])
    return paths


def age_range(age):
    """“4-7岁” → (4, 7)；“10岁+”“父母先读（孩子11岁+）” → (10, None)。"""
    nums = [int(n) for n in re.findall(r"\d+", age)]
    return nums[0], (nums[1] if len(nums) > 1 and "-" in age else None)


def write_html(rows):
    """把书单数据注入网页模板，生成可离线打开的单文件网页（只有书单列表和左侧分类筛选）。"""
    books = [{
        "theme": r["主题"], "domain": r["领域"], "title": r["书名"], "author": r["作者"], "era": r["成书年代"], "region": r["文明/地区"],
        "core": r["核心智慧"], "diff": r["难度(1-5)"], "length": r["篇幅"], "level": r["级别"],
        "position": r["内容定位"], "textbook": r["课内必读"], "weeks": r["建议用时(周)"],
        "edition": r["推荐版本/译本"], "tip": r["阅读建议"],
        "bridge": list(BRIDGE[r["书名"]]) if r["书名"] in BRIDGE else None,
        "media": MEDIA.get(r["书名"], ""),
    } for r in rows]
    kids = []
    for band, title, author, cn, en, age, play, nxt in KIDS:
        lo, hi = age_range(age)
        kids.append({"band": band, "title": title, "author": author, "cn": cn, "en": en, "age": age,
                     "ageMin": lo, "ageMax": hi, "play": play, "next": nxt, "family": title in FAMILY_READS,
                     "must": title in KID_MUST_TITLES, "textbook": TEXTBOOK_GRADE.get(title, ""),
                     "media": MEDIA.get(title, "")})
    data = {
        "meta": {"familyMark": FAMILY_MARK, "positionNote": POSITION_NOTE, "mediaNote": MEDIA_NOTE},
        "domains": [{"name": d, "emoji": DOMAIN_EMOJI[d], "theme": THEME_OF[d], "count": len(b)} for d, b in BOOKS.items()],
        "themes": [{"name": t, "emoji": e, "domains": ds, "first": first,
                    "count": sum(1 for r in rows if r["主题"] == t)} for t, e, ds, first in THEMES],
        "books": books,
        "bands": [{"name": b, "desc": desc, "emoji": e, "color": f"#{c}"}
                  for (b, desc), e, c in zip(KID_BANDS, BAND_EMOJI, BAND_COLORS)],
        "kids": kids,
    }
    with open(os.path.join(ROOT, "scripts", "booklist_template.html"), encoding="utf-8") as f:
        template = f.read()
    payload = json.dumps(data, ensure_ascii=False).replace("</", "<\\/")
    assert PWA_MARK in template, "模板缺少 PWA 标记"
    html = template.replace("/*__DATA__*/", payload).replace("__WECHAT_NAME__", WECHAT_NAME).replace("__WECHAT_KEY__", WECHAT_KEYWORD)
    path = os.path.join(OUT_DIR, "人类智慧经典书单.html")
    with open(path, "w", encoding="utf-8") as f:
        f.write(html.replace(PWA_MARK, "").replace(WXQR_MARK, wechat_qr_data_uri()))
    return path, html


# 网页里公众号二维码的占位符：单文件网页内嵌成 data URI，可离线打开；部署版用单独的图片文件，微信里长按识别更稳
WXQR_MARK, WXQR_FILE = "__WXQR__", "wechat-qr.jpg"


def wechat_qr_image():
    """公众号二维码缩到 480 像素，网页上显示 200 像素左右，高清屏也够清楚。没有图片或 Pillow 时返回 None。"""
    try:
        from PIL import Image
    except ImportError:
        return None
    if not os.path.exists(WECHAT_QR):
        return None
    return Image.open(WECHAT_QR).convert("RGB").resize((480, 480), Image.LANCZOS)


def wechat_qr_data_uri():
    import base64
    import io
    img = wechat_qr_image()
    if img is None:
        return ""
    buf = io.BytesIO()
    img.save(buf, "JPEG", quality=85)
    return "data:image/jpeg;base64," + base64.b64encode(buf.getvalue()).decode()


PWA_MARK = "<!--__PWA__-->"
PWA_HEAD = ('<link rel="manifest" href="manifest.webmanifest">\n'
            '<link rel="apple-touch-icon" href="icon-192.png">\n'
            '<meta name="apple-mobile-web-app-capable" content="yes">\n'
            '<meta name="apple-mobile-web-app-title" content="开卷有益">')
# 网页资源先用缓存，同时后台取新版；缓存名带内容哈希，重新生成后自动更新
SW_JS = """const CACHE = "booklist-__HASH__";
const FILES = ["./", "index.html", "manifest.webmanifest", "icon-192.png", "icon-512.png", "wechat-qr.jpg"];
self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES)).then(() => self.skipWaiting()));
});
self.addEventListener("activate", e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});
self.addEventListener("fetch", e => {
  if (e.request.method !== "GET" || new URL(e.request.url).origin !== location.origin) return;
  e.respondWith(caches.open(CACHE).then(c => c.match(e.request, {ignoreSearch: true}).then(hit => {
    const net = fetch(e.request).then(res => { if (res.ok) c.put(e.request, res.clone()); return res; })
      .catch(() => hit || c.match("index.html"));
    return hit || net;
  })));
});
"""


def write_pwa(html, xlsx_path=None, poster_path=None):
    """生成可部署的网站目录：index.html + manifest + service worker + 图标，手机能“添加到主屏幕”并离线使用。
    另放公众号二维码，以及 Excel 和完整书单长图（公众号自动回复里给的下载链接）。"""
    import hashlib
    import shutil
    web = os.path.join(OUT_DIR, "网页版")
    os.makedirs(web, exist_ok=True)
    html = html.replace(PWA_MARK, PWA_HEAD).replace(WXQR_MARK, WXQR_FILE)
    with open(os.path.join(web, "index.html"), "w", encoding="utf-8") as f:
        f.write(html)
    qr = wechat_qr_image()
    if qr is not None:
        qr.save(os.path.join(web, WXQR_FILE), "JPEG", quality=88)
    for src, name in ((xlsx_path, SITE_XLSX), (poster_path, SITE_POSTER)):
        if src and os.path.exists(src):
            shutil.copyfile(src, os.path.join(web, name))
    manifest = {"name": "开卷有益 · 经典书单", "short_name": "开卷有益", "start_url": "./", "scope": "./",
                "display": "standalone", "background_color": "#F5F0E6", "theme_color": "#1B2838", "lang": "zh-CN",
                "icons": [{"src": f"icon-{s}.png", "sizes": f"{s}x{s}", "type": "image/png", "purpose": "any maskable"}
                          for s in (192, 512)]}
    with open(os.path.join(web, "manifest.webmanifest"), "w", encoding="utf-8") as f:
        json.dump(manifest, f, ensure_ascii=False, indent=2)
    digest = hashlib.sha1(html.encode("utf-8")).hexdigest()[:10]
    with open(os.path.join(web, "sw.js"), "w", encoding="utf-8") as f:
        f.write(SW_JS.replace("__HASH__", digest))
    try:
        from PIL import Image, ImageDraw, ImageFont
        fonts = next((f for f in POSTER_FONTS if os.path.exists(f[2])), None)
        for s in (192, 512):
            img = Image.new("RGB", (s, s), "#B23A2E")
            d = ImageDraw.Draw(img)
            if fonts:
                f = ImageFont.truetype(fonts[2], int(s * 0.5), index=fonts[3])
                l, t, r, b = d.textbbox((0, 0), "书", font=f)
                d.text(((s - r - l) / 2, (s - b - t) / 2), "书", font=f, fill="white")
            img.save(os.path.join(web, f"icon-{s}.png"))
    except ImportError:
        pass
    return web


def main():
    rows = build_rows()
    validate(rows)
    os.makedirs(OUT_DIR, exist_ok=True)
    wb = Workbook()
    _, main_col = write_main(wb, rows)
    write_guide(wb, rows, main_col)
    write_route(wb, rows, main_col)
    write_kids(wb)
    write_year(wb, rows, main_col)
    wb.move_sheet("使用说明", offset=-wb.index(wb["使用说明"]))
    wb.move_sheet("年度12本", offset=1 - wb.index(wb["年度12本"]))
    wb.active = 0
    path = os.path.join(OUT_DIR, "人类智慧经典书单.xlsx")
    wb.save(path)
    write_csv(rows)
    md_path = write_markdown(rows)
    article_paths = write_article(rows) + [write_share_article(rows)]
    poster_path = write_poster(rows)
    year_poster_path = write_year_poster()
    full_poster_paths = write_full_poster(rows) or []
    html_path, html = write_html(rows)
    web_dir = write_pwa(html, path, full_poster_paths[0] if full_poster_paths else None)

    print(f"成人书单 {len(rows)} 本（{len(BOOKS)} 个领域），亲子共读 {len(KIDS)} 本")
    for p in (1, 2, 3, 4, 0):
        n = sum(1 for r in rows if r["阶段"] == p)
        m = sum(1 for r in rows if r["阶段"] == p and r["级别"] == "必读")
        print(f"  {PHASES[p][0]}：{n} 本（必读 {m}）")
    print(f"已生成：{path}")
    print(f"已生成：{md_path}")
    for p in article_paths:
        print(f"已生成：{p}")
    print(f"已生成：{poster_path}" if poster_path else "未生成海报：缺少 Pillow 或中文字体")
    for p in [year_poster_path] + full_poster_paths:
        if p:
            print(f"已生成：{p}")
    print(f"已生成：{html_path}")
    print(f"已生成：{web_dir}（可直接部署的 PWA 网站）")


if __name__ == "__main__":
    main()
